INSERT INTO reviewed_plant_passports VALUES
 (2,'Аглаонема Вайт Ленс','{"humidity":"Обычная комнатная влажность подходит. Если воздух очень сухой, поставьте рядом увлажнитель или поддон с влажным керамзитом так, чтобы дно горшка не стояло в воде.","temperature":"Держите в тёплом помещении примерно при 18–24 °C; берегите от холодных сквозняков и резких перепадов температуры.","soil":"Используйте рыхлый субстрат для комнатных растений с хорошим дренажом. Горшок должен иметь отверстия, чтобы вода не застаивалась у корней.","repotting":"Пересаживайте весной примерно раз в 2–3 года или раньше, когда корни заполнят горшок. Новый горшок берите лишь немного шире прежнего.","fertilizer":"С апреля по сентябрь подкармливайте удобрением для комнатных растений в половинной дозе по инструкции; зимой при слабом росте подкормку сократите.","growthRate":"Растёт постепенно; новые листья появляются активнее весной и летом, а зимой при коротком световом дне рост замедляется."}'::jsonb),
